#!/usr/bin/env node
// Re-derive the releases whose inputs are all in this repository.
//
//   node pipeline/rebuild.mjs           rebuild: writes downloads/ and src/lib/
//   node pipeline/rebuild.mjs --check   verify byte for byte, write nothing
//
// The builders read the study's own layout, with the releases under
// public/downloads/; this links that path to the repository's downloads/
// folder first (a junction on Windows). Generated by the study's source
// repository (scripts/uavocab/build-open-repo.mjs); do not edit.

import { spawnSync } from "node:child_process";
import { existsSync, lstatSync, mkdirSync, symlinkSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const BUILDERS = [
  "build-release.mjs",
  "build-stress.mjs",
  "build-dictionary.mjs",
  "build-stress-audit.mjs",
];

const link = path.join(HERE, "public", "downloads", "ukrainian-frequency");
const target = path.join(HERE, "..", "downloads", "ukrainian-frequency");
let present = false;
try {
  lstatSync(link);
  present = true;
} catch {}
if (!present) {
  mkdirSync(path.dirname(link), { recursive: true });
  if (process.platform === "win32") symlinkSync(target, link, "junction");
  else symlinkSync(path.relative(path.dirname(link), target), link, "dir");
}
if (!existsSync(path.join(link, "latest.json"))) {
  console.error(`${path.relative(process.cwd(), link)} does not lead to the releases; remove it and run again`);
  process.exit(1);
}

const check = process.argv.includes("--check");
const failed = [];
for (const b of BUILDERS) {
  const r = spawnSync(process.execPath, [path.join(HERE, "scripts", "ukrainian-frequency", b), ...(check ? ["--check"] : [])], { stdio: "inherit", cwd: HERE });
  if (r.status !== 0) failed.push(b);
}
if (failed.length) {
  console.error(`${failed.length} of ${BUILDERS.length} builders ${check ? "did not reproduce their release" : "failed"}: ${failed.join(", ")}`);
  process.exit(1);
}
console.log(check ? `all ${BUILDERS.length} releases re-derive byte for byte` : `rebuilt ${BUILDERS.length} releases; check them with python3 scripts/verify.py`);
